const keyOf = (r, c) => `${r}-${c}`;
const rowLetter = (i) => {
  let s = ""; i += 1;
  while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); }
  return s;
};
const fmtDate = (d) => { try { return new Date(d).toLocaleDateString("tr-TR", { day: "2-digit", month: "long", year: "numeric" }); } catch (e) { return d; } };
