/* ---------- data migration / normalization ---------- */
function normalizeHall(h) {
  const empty = () => ({ rows: 6, cols: 8, stagePos: "top", cellAisle: {}, blocks: defaultBlocks(150, 250), cellBlock: {}, cellDeleted: {}, cellPrice: {}, numberingMode: "rowLetter", oddEvenDirection: "oddLeft", cellLabelOverride: {}, cellBlocked: {} });
  if (!h || typeof h !== "object") return empty();
  if (Array.isArray(h.blocks) && h.blocks.length > 0) {
    return {
      rows: h.rows || 6, cols: h.cols || 8, stagePos: h.stagePos || "top",
      cellAisle: h.cellAisle || {}, cellDeleted: h.cellDeleted || {}, cellPrice: h.cellPrice || {},
      blocks: h.blocks.map((b) => ({ ...b, letter: b.letter || "" })), cellBlock: h.cellBlock || {},
      numberingMode: ["rowLetter", "oddEven", "sequential"].includes(h.numberingMode) ? h.numberingMode : "rowLetter",
      oddEvenDirection: h.oddEvenDirection === "evenLeft" ? "evenLeft" : "oddLeft",
      cellLabelOverride: h.cellLabelOverride || {},
      cellBlocked: h.cellBlocked || {},
    };
  }
  // legacy std/vip shape
  if (h.priceStd != null || h.cellVip) {
    return {
      rows: h.rows || 6, cols: h.cols || 8, stagePos: h.stagePos || "top",
      cellAisle: h.cellAisle || {}, cellDeleted: h.cellDeleted || {}, cellPrice: h.cellPrice || {},
      blocks: defaultBlocks(h.priceStd ?? 150, h.priceVip ?? 250),
      cellBlock: Object.fromEntries(Object.keys(h.cellVip || {}).map((k) => [k, "vip"])),
      numberingMode: "rowLetter", oddEvenDirection: "oddLeft", cellLabelOverride: {}, cellBlocked: {},
    };
  }
  return empty();
}
function computeSeatLabels(hall) {
  const labels = {};
  const mode = hall.numberingMode || "rowLetter";

  if (mode === "rowLetter") {
    for (let r = 0; r < hall.rows; r++) {
      let n = 1;
      for (let c = 0; c < hall.cols; c++) {
        const key = keyOf(r, c);
        if (hall.cellDeleted[key] || hall.cellAisle[key]) continue;
        labels[key] = `${rowLetter(r)}${n}`;
        n++;
      }
    }
  } else {
    const counters = {};
    const getBlockId = (key) => hall.cellBlock[key] || hall.blocks[0]?.id;
    const counterFor = (blockId) => (counters[blockId] || (counters[blockId] = { odd: 1, even: 2, seq: 1 }));
    const letterFor = (key) => { const b = hall.blocks.find((bl) => bl.id === getBlockId(key)) || hall.blocks[0]; return b?.letter || ""; };
    const oddLeft = hall.oddEvenDirection !== "evenLeft";

    for (let r = 0; r < hall.rows; r++) {
      const segments = [];
      let current = [];
      for (let c = 0; c < hall.cols; c++) {
        const key = keyOf(r, c);
        if (hall.cellDeleted[key]) continue;
        if (hall.cellAisle[key]) { if (current.length) { segments.push(current); current = []; } continue; }
        current.push(key);
      }
      if (current.length) segments.push(current);

      if (mode === "oddEven" && segments.length === 2) {
        const [leftSeg, rightSeg] = segments;
        leftSeg.forEach((key) => {
          const ctr = counterFor(getBlockId(key));
          const n = oddLeft ? ctr.odd : ctr.even;
          if (oddLeft) ctr.odd += 2; else ctr.even += 2;
          labels[key] = `${letterFor(key)}${n}`;
        });
        rightSeg.forEach((key) => {
          const ctr = counterFor(getBlockId(key));
          const n = oddLeft ? ctr.even : ctr.odd;
          if (oddLeft) ctr.even += 2; else ctr.odd += 2;
          labels[key] = `${letterFor(key)}${n}`;
        });
      } else {
        segments.forEach((seg) => seg.forEach((key) => {
          const ctr = counterFor(getBlockId(key));
          const n = ctr.seq; ctr.seq += 1;
          labels[key] = `${letterFor(key)}${n}`;
        }));
      }
    }
  }

  if (hall.cellLabelOverride) {
    Object.entries(hall.cellLabelOverride).forEach(([key, val]) => { if (val) labels[key] = val; });
  }
  return labels;
}
function seatLabel(hall, key) {
  return computeSeatLabels(hall)[key] || "";
}
