/* ---------- Home ---------- */
function HomePage({ shows, events, carousel, comments, go, openShow }) {
  const [slide, setSlide] = useState(0);
  const isMobile = useIsMobile();
  const withShow = events.map((ev) => ({ ev, show: shows.find((s) => s.id === ev.showId) })).filter((x) => x.show);
  const heroItems = carousel && carousel.length > 0
    ? carousel.map((c) => ({ key: c.id, image: c.image, title: c.title, subtitle: c.subtitle, onClick: () => c.showId && openShow(c.showId) }))
    : withShow.slice(0, 5).map(({ ev, show }) => ({ key: ev.id, image: show.poster, title: show.title, subtitle: `${fmtDate(ev.date)} · ${ev.time} · ${ev.location}`, onClick: () => openShow(show.id, ev.id) }));
  useEffect(() => { const t = setInterval(() => setSlide((s) => (heroItems.length ? (s + 1) % heroItems.length : 0)), 4500); return () => clearInterval(t); }, [heroItems.length]);
  const newToOld = [...withShow].sort((a, b) => new Date(b.ev.date) - new Date(a.ev.date));
  const upcoming = [...withShow].filter((x) => new Date(x.ev.date) >= new Date(new Date().toDateString())).sort((a, b) => new Date(a.ev.date) - new Date(b.ev.date));
  const recentComments = (comments || []).filter((c) => c.status === "approved").sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 5);

  return (
    <div>
      <div style={{ position: "relative", height: isMobile ? 340 : 560, overflow: "hidden", background: CURTAIN_DARK }}>
        {heroItems.map((item, i) => (
          <div key={item.key} style={{ position: "absolute", inset: 0, opacity: i === slide ? 1 : 0, transition: "opacity 0.7s ease" }}>
            {item.image ? <Img src={item.image} alt={item.title} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} /> : <div style={{ width: "100%", height: "100%", background: `linear-gradient(120deg, ${CURTAIN_DARK}, ${CURTAIN})` }} />}
            <div style={{ position: "absolute", inset: 0, background: "linear-gradient(0deg, rgba(20,16,14,0.75), transparent 60%)", display: "flex", alignItems: "flex-end", padding: isMobile ? 18 : 32 }}>
              <div style={{ color: CREAM }}>
                <div style={{ fontSize: isMobile ? 20 : 30 }}>{item.title}</div>
                {item.subtitle && <div style={{ fontSize: isMobile ? 12 : 14, opacity: 0.85, marginTop: 6 }}>{item.subtitle}</div>}
                {item.onClick && <button onClick={item.onClick} style={{ ...btnPrimary, marginTop: isMobile ? 10 : 14, fontSize: isMobile ? 13 : 14, padding: isMobile ? "8px 16px" : "10px 18px" }}>Detayları Gör</button>}
              </div>
            </div>
          </div>
        ))}
        {heroItems.length > 1 && (
          <div style={{ position: "absolute", bottom: 14, right: 24, display: "flex", gap: 6 }}>
            {heroItems.map((_, i) => <button key={i} onClick={() => setSlide(i)} style={{ width: 8, height: 8, borderRadius: 4, border: "none", background: i === slide ? GOLD : "rgba(255,255,255,0.5)", cursor: "pointer" }} />)}
          </div>
        )}
      </div>

      <div style={{ padding: isMobile ? "24px 16px" : "36px 24px" }}>
        <div style={{ fontSize: 22, marginBottom: 16 }}>Oyunlarımız</div>
        <div style={{ display: "flex", gap: 16, overflowX: "auto", paddingBottom: 8 }}>
          {newToOld.map(({ ev, show }) => (
            <div key={ev.id} onClick={() => openShow(show.id, ev.id)} style={{ width: 150, minWidth: 150, flexShrink: 0, cursor: "pointer" }}>
              <Poster url={show.poster} title={show.title} />
              <div style={{ fontSize: 13, marginTop: 6 }}>{show.title}</div>
              <div style={{ fontSize: 11, color: MUTE }}>{fmtDate(ev.date)}</div>
            </div>
          ))}
          {newToOld.length === 0 && <div style={{ color: MUTE, fontSize: 13 }}>Henüz etkinlik eklenmedi.</div>}
        </div>
      </div>

      <div style={{ padding: isMobile ? "0 16px 40px" : "0 24px 40px", display: "flex", gap: 24, flexDirection: isMobile ? "column" : "row", alignItems: "flex-start" }}>
        <div style={{ flex: isMobile ? "1 1 auto" : "1 1 58%", minWidth: 0, width: isMobile ? "100%" : undefined }}>
          <div style={{ fontSize: 22, marginBottom: 16 }}>En Yakın Oyunlarımız</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {upcoming.map(({ ev, show }) => (
              <div key={ev.id} onClick={() => openShow(show.id, ev.id)} style={{ display: "flex", gap: 14, alignItems: "center", background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 12, cursor: "pointer" }}>
                <div style={{ width: 64 }}><Poster url={show.poster} title={show.title} /></div>
                <div>
                  <div style={{ fontSize: 15 }}>{show.title}</div>
                  <div style={{ fontSize: 12, color: MUTE, display: "flex", gap: 10, flexWrap: "wrap", marginTop: 4 }}>
                    <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Calendar size={12} /> {fmtDate(ev.date)}</span>
                    <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Clock size={12} /> {ev.time}</span>
                    <span style={{ display: "flex", alignItems: "center", gap: 4 }}><MapPin size={12} /> {ev.location}</span>
                  </div>
                </div>
              </div>
            ))}
            {upcoming.length === 0 && <div style={{ color: MUTE, fontSize: 13 }}>Yaklaşan oyun yok.</div>}
          </div>
        </div>

        <div style={{ flex: isMobile ? "1 1 auto" : "1 1 34%", minWidth: 0, width: isMobile ? "100%" : undefined }}>
          <div style={{ fontSize: 22, marginBottom: 16 }}>Son Yorumlar</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {recentComments.map((c) => {
              const cShow = shows.find((s) => s.id === c.showId);
              return (
                <div key={c.id} onClick={() => cShow && openShow(cShow.id)} style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 12, cursor: cShow ? "pointer" : "default" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                    <div style={{ width: 26, height: 26, borderRadius: "50%", overflow: "hidden", background: CREAM, flexShrink: 0 }}><Img src={c.userPhoto} style={{ width: "100%", height: "100%", objectFit: "cover" }} /></div>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 13 }}>{c.userName}</div>
                      {cShow && <div style={{ fontSize: 11, color: MUTE }}>{cShow.title}</div>}
                    </div>
                  </div>
                  <div style={{ fontSize: 13, color: "#3A322C" }}>{c.text}</div>
                </div>
              );
            })}
            {recentComments.length === 0 && <div style={{ color: MUTE, fontSize: 13 }}>Henüz yorum yok.</div>}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------- Shows list ---------- */
const GENRES = ["komedi", "dram", "belgesel"];
function ShowsPage({ shows, events, openShow }) {
  const [cat, setCat] = useState("all");
  const [genre, setGenre] = useState("all");
  const filtered = shows.filter((s) => (cat === "all" || s.category === cat) && (genre === "all" || s.genre === genre));
  const nextEvent = (showId) => {
    const upcoming = events.filter((e) => e.showId === showId && new Date(e.date) >= new Date(new Date().toDateString())).sort((a, b) => new Date(a.date) - new Date(b.date));
    return upcoming[0] || null;
  };
  const sorted = [...filtered].sort((a, b) => {
    const na = nextEvent(a.id), nb = nextEvent(b.id);
    if (na && nb) return new Date(na.date) - new Date(nb.date);
    if (na) return -1;
    if (nb) return 1;
    return a.title.localeCompare(b.title, "tr");
  });
  return (
    <div style={{ padding: 24 }}>
      <div style={{ fontSize: 24, marginBottom: 16 }}>Oyunlar</div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
        {[["all", "Tümü"], ["cocuk", "Çocuk"], ["yetiskin", "Yetişkin"]].map(([id, label]) => (
          <button key={id} onClick={() => setCat(id)} style={btnGhost(cat === id)}>{label}</button>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 22 }}>
        <button onClick={() => setGenre("all")} style={btnGhost(genre === "all")}>Tüm Türler</button>
        {GENRES.map((g) => <button key={g} onClick={() => setGenre(g)} style={btnGhost(genre === g)}>{g[0].toUpperCase() + g.slice(1)}</button>)}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))", gap: 18 }}>
        {sorted.map((s) => {
          const ev = nextEvent(s.id);
          return (
            <div key={s.id} onClick={() => openShow(s.id, ev?.id)} style={{ cursor: "pointer" }}>
              <Poster url={s.poster} title={s.title} />
              <div style={{ fontSize: 13, marginTop: 6 }}>{s.title}</div>
              <div style={{ fontSize: 11, color: MUTE }}>{ev ? fmtDate(ev.date) : "Yaklaşan seans yok"}</div>
            </div>
          );
        })}
        {sorted.length === 0 && <div style={{ color: MUTE, fontSize: 13 }}>Bu filtrelere uyan oyun yok.</div>}
      </div>
    </div>
  );
}

/* ---------- Show detail (+ booking) ---------- */
function ShowDetail({ show, events, team, contact, bookings, onBook, backToShows, initialEventId, currentUser, onOpenAccount, comments, onAddComment, onEditComment, onDeleteComment, externalTicketLinks, updateBookings, infoPage }) {
  const HOLD_MS = 5 * 60 * 1000;
  const sessionIdRef = useRef(uid());
  const showEvents = events.filter((e) => e.showId === show.id).sort((a, b) => new Date(a.date) - new Date(b.date));
  const upcomingEvents = showEvents.filter((e) => new Date(e.date) >= new Date(new Date().toDateString()));
  const [selectedEventId, setSelectedEventId] = useState(initialEventId || upcomingEvents[0]?.id || showEvents[0]?.id || null);
  const selectedEvent = showEvents.find((e) => e.id === selectedEventId) || null;

  const [lightbox, setLightbox] = useState(null);
  const [selected, setSelected] = useState([]);
  const [checkout, setCheckout] = useState(false);
  const [confirmed, setConfirmed] = useState(null);
  const [holdDeadline, setHoldDeadline] = useState(null);
  const [timedOut, setTimedOut] = useState(false);
  const [now, setNow] = useState(Date.now());

  const releaseMyHolds = (eventId, keys) => {
    const evB = bookings[eventId];
    if (!evB || !evB.holds) return;
    const holds = { ...evB.holds };
    let changed = false;
    keys.forEach((k) => { if (holds[k]?.sessionId === sessionIdRef.current) { delete holds[k]; changed = true; } });
    if (changed) updateBookings({ ...bookings, [eventId]: { ...evB, holds } });
  };

  useEffect(() => {
    setSelected([]); setConfirmed(null); setCheckout(false); setHoldDeadline(null); setTimedOut(false);
  }, [selectedEventId]);

  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (holdDeadline && now >= holdDeadline && selectedEvent) {
      releaseMyHolds(selectedEvent.id, selected);
      setSelected([]);
      setHoldDeadline(null);
      setTimedOut(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [now, holdDeadline]);

  const evBooking = selectedEvent ? bookings[selectedEvent.id] : null;
  const booked = evBooking?.bookedSeats || {};
  const heldByOthers = {};
  if (evBooking?.holds) {
    Object.entries(evBooking.holds).forEach(([k, h]) => {
      if (h.expiresAt > now && h.sessionId !== sessionIdRef.current) heldByOthers[k] = true;
    });
  }
  const bookedForDisplay = { ...booked, ...heldByOthers, ...(selectedEvent?.hall.cellBlocked || {}) };
  const showTeam = team.filter((t) => show.teamIds.includes(t.id));
  const total = selectedEvent ? selected.reduce((sum, k) => sum + seatInfo(selectedEvent.hall, k).price, 0) : 0;

  const toggleSeat = (key) => {
    if (!selectedEvent) return;
    const isSelected = selected.includes(key);
    const next = isSelected ? selected.filter((k) => k !== key) : [...selected, key];
    setSelected(next);
    setTimedOut(false);

    const evB = bookings[selectedEvent.id] || { bookedSeats: {}, orders: [] };
    const holds = { ...(evB.holds || {}) };
    if (isSelected) delete holds[key];
    else holds[key] = { expiresAt: Date.now() + HOLD_MS, sessionId: sessionIdRef.current };
    updateBookings({ ...bookings, [selectedEvent.id]: { ...evB, holds } });

    if (next.length && !holdDeadline) setHoldDeadline(Date.now() + HOLD_MS);
    if (!next.length) setHoldDeadline(null);
  };
  const shareText = encodeURIComponent(selectedEvent ? `${show.title} — ${fmtDate(selectedEvent.date)} ${selectedEvent.time}, ${selectedEvent.location}` : show.title);

  const isMobile = useIsMobile();

  return (
    <div style={{ padding: isMobile ? "16px" : 24, maxWidth: 1100, margin: "0 auto" }}>
      <button onClick={backToShows} style={{ background: "none", border: "none", color: MUTE, cursor: "pointer", fontFamily: SERIF, marginBottom: 14, display: "flex", alignItems: "center", gap: 4 }}><ChevronLeft size={16} /> Oyunlara dön</button>

      <div style={{ display: "flex", gap: isMobile ? 16 : 28, flexWrap: "wrap", marginBottom: 28, ...(isMobile ? { flexDirection: "column", alignItems: "center", textAlign: "center" } : {}) }}>
        <div style={{ width: isMobile ? 170 : 260 }}><Poster url={show.poster} title={show.title} /></div>
        <div style={{ flex: "1 1 320px", minWidth: 0 }}>
          <div style={{ fontSize: isMobile ? 22 : 28, color: CURTAIN, marginBottom: 12 }}>{show.title}</div>
          <div style={{ fontSize: 14, marginBottom: 6 }}>Oyun Ekibi</div>
          <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 16, justifyContent: isMobile ? "center" : "flex-start" }}>
            {showTeam.map((t) => (
              <div key={t.id} style={{ width: 90, textAlign: "center" }}>
                <div style={{ width: 56, height: 56, borderRadius: "50%", background: CREAM, margin: "0 auto 6px", overflow: "hidden" }}>
                  {t.photo && <img src={t.photo} alt={t.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />}
                </div>
                <div style={{ fontSize: 12 }}>{t.name}</div>
                <div style={{ fontSize: 11, color: MUTE }}>{t.role}</div>
              </div>
            ))}
            {show.guestCrew.filter((g) => g.name).map((g) => (
              <div key={g.id} style={{ width: 90, textAlign: "center" }}>
                <div style={{ width: 56, height: 56, borderRadius: "50%", background: CREAM, margin: "0 auto 6px" }} />
                <div style={{ fontSize: 12 }}>{g.name}</div>
                <div style={{ fontSize: 11, color: MUTE }}>{g.role || "Misafir"}</div>
              </div>
            ))}
            {showTeam.length === 0 && show.guestCrew.filter((g) => g.name).length === 0 && <div style={{ fontSize: 12, color: MUTE }}>Ekip henüz atanmadı.</div>}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <a href={`https://wa.me/?text=${shareText}`} target="_blank" rel="noreferrer" style={{ ...btnGhost(false), textDecoration: "none", display: "flex", alignItems: "center", gap: 6 }}><Share2 size={13} /> WhatsApp</a>
            <a href={`https://twitter.com/intent/tweet?text=${shareText}`} target="_blank" rel="noreferrer" style={{ ...btnGhost(false), textDecoration: "none" }}>X</a>
            <a href={`https://www.facebook.com/sharer/sharer.php?u=${shareText}`} target="_blank" rel="noreferrer" style={{ ...btnGhost(false), textDecoration: "none" }}>Facebook</a>
          </div>
        </div>
      </div>

      {show.teaser && (
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontSize: 16, marginBottom: 8 }}>Teaser</div>
          <video src={show.teaser} controls style={{ width: "100%", maxWidth: 640, borderRadius: 8 }} />
        </div>
      )}

      {show.gallery.length > 0 && (
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontSize: 16, marginBottom: 8 }}>Fotoğraf Galerisi</div>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            {show.gallery.map((g, i) => (
              <div key={i} onClick={() => setLightbox({ type: "photo", url: g })} style={{ width: 110, height: 110, borderRadius: 6, overflow: "hidden", cursor: "pointer", background: CREAM }}>
                {g && <Img src={g} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />}
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 16, marginBottom: 8 }}>Oyun Hakkında</div>
        <div style={{ fontSize: 14, lineHeight: 1.7, color: "#3A322C", maxWidth: 700 }} dangerouslySetInnerHTML={{ __html: show.description }} />
      </div>

      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 16, marginBottom: 10 }}>Seanslar</div>
        {showEvents.length === 0 ? (
          <div style={{ fontSize: 13, color: MUTE }}>Bu oyun için henüz bir etkinlik (tarih) eklenmedi.</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 8, maxWidth: 520 }}>
            {showEvents.map((ev) => (
              <div key={ev.id} onClick={() => setSelectedEventId(ev.id)} style={{ display: "flex", gap: 10, alignItems: "center", padding: "10px 14px", borderRadius: 8, border: `1px solid ${selectedEventId === ev.id ? CURTAIN : LINE}`, background: selectedEventId === ev.id ? CREAM : "white", cursor: "pointer", fontSize: 13 }}>
                <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Calendar size={13} /> {fmtDate(ev.date)}</span>
                <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Clock size={13} /> {ev.time}</span>
                <span style={{ display: "flex", alignItems: "center", gap: 4, color: MUTE }}><MapPin size={13} /> {ev.location}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {externalTicketLinks && externalTicketLinks.filter((l) => l.label).length > 0 && (
        <div style={{ marginBottom: 28, background: CREAM, borderRadius: 8, padding: 16, maxWidth: 620 }}>
          <div style={{ fontSize: 13, marginBottom: 10 }}>Bu oyunun biletini ayrıca {externalTicketLinks.filter((l) => l.label).map((l) => l.label).join(", ")} sitelerinden de kredi kartınızla alabilirsiniz.</div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {externalTicketLinks.filter((l) => l.label).map((l) => (
              <a key={l.id} href={l.url || "#"} target="_blank" rel="noreferrer" style={{ padding: "8px 16px", borderRadius: 999, background: l.color, color: "white", fontSize: 13, textDecoration: "none" }}>{l.label}</a>
            ))}
          </div>
        </div>
      )}

      {selectedEvent && (
        <div style={{ borderTop: `1px solid ${LINE}`, paddingTop: 24 }}>
          <div style={{ fontSize: 18, marginBottom: 6 }}>Koltuk Seçimi <span style={{ fontSize: 13, color: MUTE, fontWeight: "normal" }}>· {fmtDate(selectedEvent.date)} {selectedEvent.time}, {selectedEvent.location}</span></div>
          {selectedEvent.address && (
            <div style={{ marginBottom: 16, maxWidth: 480 }}>
              <MapEmbed address={selectedEvent.address} height={160} />
            </div>
          )}
          {confirmed ? (
            <div style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 24, textAlign: "center", maxWidth: 460 }}>
              <div style={{ width: 44, height: 44, borderRadius: "50%", background: CURTAIN, color: CREAM, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 12px" }}><Check size={20} /></div>
              <div style={{ fontSize: 17, marginBottom: 6 }}>Talebiniz alındı</div>
              <div style={{ fontSize: 13, color: MUTE }}>Sipariş No: <strong style={{ color: INK }}>{confirmed.id}</strong><br />Ödemeniz onaylandıktan sonra biletiniz e-posta ile gönderilecek.</div>
            </div>
          ) : (
            <div style={{ display: "flex", gap: 20, flexWrap: "wrap" }}>
              <div style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 20, flex: "1 1 320px", overflowX: "auto" }}>
                <SeatGrid hall={selectedEvent.hall} booked={bookedForDisplay} selected={selected} onSeatClick={toggleSeat} />
                <div style={{ display: "flex", gap: 14, marginTop: 16, fontSize: 12, color: MUTE, flexWrap: "wrap" }}>
                  {selectedEvent.hall.blocks.map((b) => (
                    <span key={b.id}><span style={{ display: "inline-block", width: 10, height: 10, borderRadius: 3, background: b.color, marginRight: 5 }} />{b.letter ? `${b.letter} · ` : ""}{b.name} {b.price}₺</span>
                  ))}
                  <span><span style={{ display: "inline-block", width: 10, height: 10, borderRadius: 3, background: "#D8D2C4", marginRight: 5 }} />Dolu</span>
                </div>
                {timedOut && <div style={{ marginTop: 14, fontSize: 12, color: CURTAIN, background: CREAM, borderRadius: 6, padding: "8px 12px" }}>Süreniz doldu, seçtiğiniz koltuklar serbest bırakıldı. Lütfen tekrar seçin.</div>}
              </div>
              <div style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 20, width: 220, height: "fit-content" }}>
                <div style={{ fontSize: 14, marginBottom: 10 }}>Özet</div>
                {holdDeadline && (
                  <div style={{ fontSize: 12, marginBottom: 12, padding: "6px 10px", borderRadius: 6, background: holdDeadline - now < 60000 ? "#FBEFC2" : CREAM, color: holdDeadline - now < 60000 ? CURTAIN : MUTE, textAlign: "center" }}>
                    Koltuklarınız <strong>{Math.floor(Math.max(0, holdDeadline - now) / 60000)}:{String(Math.floor((Math.max(0, holdDeadline - now) % 60000) / 1000)).padStart(2, "0")}</strong> içinde serbest bırakılacak
                  </div>
                )}
                {selected.length === 0 ? <div style={{ fontSize: 12, color: MUTE, marginBottom: 12 }}>Koltuk seçin.</div> : (
                  <div style={{ fontSize: 12, marginBottom: 12, display: "flex", flexDirection: "column", gap: 4 }}>
                    {selected.map((k) => { return <div key={k} style={{ display: "flex", justifyContent: "space-between" }}><span>{seatLabel(selectedEvent.hall, k)}</span><span>{seatInfo(selectedEvent.hall, k).price}₺</span></div>; })}
                  </div>
                )}
                <div style={{ borderTop: `1px solid ${LINE}`, paddingTop: 8, display: "flex", justifyContent: "space-between", fontSize: 14, marginBottom: 12 }}><span>Toplam</span><strong>{total}₺</strong></div>
                <button disabled={!selected.length} onClick={() => setCheckout(true)} style={{ ...btnPrimary, width: "100%", opacity: selected.length ? 1 : 0.5, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}><Ticket size={15} /> Bilet Al</button>
              </div>
            </div>
          )}
        </div>
      )}

      <CommentsSection show={show} showEvents={showEvents} bookings={bookings} comments={comments} currentUser={currentUser} onOpenAccount={onOpenAccount} onAdd={onAddComment} onEdit={onEditComment} onDelete={onDeleteComment} />

      {checkout && selectedEvent && (
        <CheckoutModal contact={contact} total={total} selectedCount={selected.length} onClose={() => setCheckout(false)} currentUser={currentUser} onOpenAccount={onOpenAccount} infoPage={infoPage}
          onConfirm={(buyer, method, ref, receipt) => {
            const order = onBook(selectedEvent.id, selected, total, buyer, method, ref, currentUser?.id, receipt);
            setConfirmed(order); setSelected([]); setCheckout(false); setHoldDeadline(null);
          }} />
      )}
      <Lightbox item={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}

function CommentsSection({ show, showEvents, bookings, comments, currentUser, onOpenAccount, onAdd, onEdit, onDelete }) {
  const [text, setText] = useState("");
  const [editing, setEditing] = useState(false);

  const approved = comments.filter((c) => c.showId === show.id && c.status === "approved").sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  const myComment = currentUser ? comments.find((c) => c.showId === show.id && c.userId === currentUser.id) : null;
  const showEventIds = showEvents.map((e) => e.id);
  const hasTicket = !!currentUser && showEventIds.some((id) => (bookings[id]?.orders || []).some((o) => o.userId === currentUser.id && o.status !== "İptal Edildi"));

  useEffect(() => { if (myComment) setText(myComment.text); }, [myComment?.id]);

  const submit = () => {
    if (!text.trim()) return;
    if (myComment) { onEdit(myComment.id, text.trim()); setEditing(false); }
    else onAdd(show.id, text);
  };

  return (
    <div style={{ borderTop: `1px solid ${LINE}`, paddingTop: 24, marginTop: 28 }}>
      <div style={{ fontSize: 18, marginBottom: 16 }}>Yorumlar</div>

      {!currentUser && (
        <div style={{ fontSize: 13, color: MUTE, marginBottom: 20 }}>
          Yorum yapmak için <button onClick={onOpenAccount} style={{ background: "none", border: "none", color: CURTAIN, cursor: "pointer", fontFamily: SERIF, fontSize: 13, padding: 0 }}>giriş yapın</button> ve bu oyun için bilet satın alın.
        </div>
      )}
      {currentUser && !hasTicket && !myComment && (
        <div style={{ fontSize: 13, color: MUTE, marginBottom: 20 }}>Bu oyuna yorum yapabilmek için önce bilet satın almış olmanız gerekir.</div>
      )}
      {currentUser && hasTicket && (!myComment || editing) && (
        <div style={{ marginBottom: 24 }}>
          <textarea rows={3} style={{ ...inputStyle, resize: "vertical", maxWidth: 520 }} value={text} onChange={(e) => setText(e.target.value)} placeholder="Bu oyun hakkındaki düşüncelerinizi paylaşın…" />
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <button onClick={submit} style={btnPrimary}>{myComment ? "Kaydet" : "Yorumu Gönder"}</button>
            {editing && <button onClick={() => { setEditing(false); setText(myComment.text); }} style={btnGhost(false)}>Vazgeç</button>}
          </div>
          <div style={{ fontSize: 11, color: MUTE, marginTop: 6 }}>Yorumunuz, yayınlanmadan önce yönetici onayından geçer.</div>
        </div>
      )}
      {currentUser && myComment && !editing && (
        <div style={{ background: CREAM, borderRadius: 8, padding: 14, marginBottom: 24, maxWidth: 520 }}>
          <div style={{ fontSize: 11, color: MUTE, marginBottom: 6 }}>Sizin yorumunuz · {myComment.status === "approved" ? "Yayında" : myComment.status === "pending" ? "Onay bekliyor" : "Reddedildi"}</div>
          <div style={{ fontSize: 13, marginBottom: 10 }}>{myComment.text}</div>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setEditing(true)} style={btnGhost(false)}>Düzenle</button>
            <button onClick={() => onDelete(myComment.id)} style={{ ...btnGhost(false), color: CURTAIN }}>Sil</button>
          </div>
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 14, maxWidth: 640 }}>
        {approved.filter((c) => c.userId !== currentUser?.id).map((c) => (
          <div key={c.id} style={{ display: "flex", gap: 10 }}>
            <div style={{ width: 36, height: 36, borderRadius: "50%", overflow: "hidden", background: CREAM, flexShrink: 0 }}><Img src={c.userPhoto} style={{ width: "100%", height: "100%", objectFit: "cover" }} /></div>
            <div>
              <div style={{ fontSize: 13 }}>{c.userName}</div>
              <div style={{ fontSize: 13, color: "#3A322C", marginTop: 2 }}>{c.text}</div>
            </div>
          </div>
        ))}
        {approved.length === 0 && <div style={{ fontSize: 13, color: MUTE }}>Henüz onaylanmış yorum yok.</div>}
      </div>
    </div>
  );
}

