/* ---------- Apply (dynamic forms) ---------- */
function ApplyPage({ forms, onSubmit, forcedFormId }) {
  const active = forms.filter((f) => f.active);
  const [formId, setFormId] = useState(forcedFormId || active[0]?.id);
  const form = (forcedFormId ? active.find((f) => f.id === forcedFormId) : active.find((f) => f.id === formId)) || active[0];
  const [values, setValues] = useState({});
  const [done, setDone] = useState(false);
  const [uploadingId, setUploadingId] = useState(null);

  if (!form) return <div style={{ padding: 24, color: MUTE }}>Şu anda açık bir başvuru formu yok.</div>;

  const setVal = (fid, v) => setValues((s) => ({ ...s, [fid]: v }));
  const submit = () => {
    for (const f of form.fields) if (f.type !== "section" && f.required && !values[f.id]) { alert("Lütfen zorunlu alanları doldurun: " + f.label); return; }
    onSubmit(form.id, values);
    setDone(true); setValues({});
  };

  const uploadSingle = async (f, e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setUploadingId(f.id);
    try {
      const dataUrl = await fileToDataURL(file);
      const key = imgKey("form-upload", form.id, uid());
      await window.storage.set(key, dataUrl, true);
      imgCache[key] = dataUrl;
      setVal(f.id, { key, name: file.name });
    } catch (err) { window.alert("Dosya yüklenemedi."); }
    setUploadingId(null);
  };
  const uploadMulti = async (f, e) => {
    const files = Array.from(e.target.files || []);
    e.target.value = "";
    if (!files.length) return;
    setUploadingId(f.id);
    const existing = values[f.id] || [];
    const added = [];
    for (const file of files) {
      try {
        const dataUrl = await fileToDataURL(file);
        const key = imgKey("form-upload", form.id, uid());
        await window.storage.set(key, dataUrl, true);
        imgCache[key] = dataUrl;
        added.push({ key, name: file.name });
      } catch (err) { window.alert(`"${file.name}" yüklenemedi, atlanıyor.`); }
    }
    setVal(f.id, [...existing, ...added]);
    setUploadingId(null);
  };

  return (
    <div style={{ padding: 24, maxWidth: 640, margin: "0 auto" }}>
      <div style={{ fontSize: 24, marginBottom: 6 }}>{forcedFormId ? form.title : "Başvurular"}</div>
      {!forcedFormId && active.length > 1 && (
        <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
          {active.map((f) => <button key={f.id} onClick={() => { setFormId(f.id); setDone(false); }} style={btnGhost(form.id === f.id)}>{f.title}</button>)}
        </div>
      )}
      <div style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 24 }}>
        <div style={{ fontSize: 17, marginBottom: 16 }}>{form.title}</div>
        {done ? (
          <div style={{ fontSize: 14, color: MUTE }}><Check size={16} style={{ verticalAlign: "middle", marginRight: 6, color: CURTAIN }} />Başvurunuz alındı, teşekkür ederiz.</div>
        ) : (
          <>
            {form.fields.map((f) => {
              if (f.type === "section") {
                return <div key={f.id} style={{ fontSize: 15, marginTop: 20, marginBottom: 10, paddingTop: 14, borderTop: `1px solid ${LINE}`, color: CURTAIN }}>{f.label}</div>;
              }
              return (
                <Field key={f.id} label={f.label + (f.required ? " *" : "")}>
                  {f.type === "textarea" ? <textarea rows={4} style={{ ...inputStyle, resize: "vertical" }} value={values[f.id] || ""} onChange={(e) => setVal(f.id, e.target.value)} />
                    : f.type === "select" ? (
                      <select style={inputStyle} value={values[f.id] || ""} onChange={(e) => setVal(f.id, e.target.value)}>
                        <option value="">Seçin</option>
                        {(f.options || []).map((o) => <option key={o} value={o}>{o}</option>)}
                      </select>
                    ) : f.type === "checkbox" ? (
                      <label style={{ fontSize: 13, display: "flex", gap: 6, alignItems: "center" }}><input type="checkbox" checked={!!values[f.id]} onChange={(e) => setVal(f.id, e.target.checked)} /> Evet</label>
                    ) : f.type === "number" ? (
                      <input type="number" style={inputStyle} value={values[f.id] || ""} onChange={(e) => setVal(f.id, e.target.value)} />
                    ) : f.type === "file" ? (
                      <div>
                        {values[f.id]?.name && <div style={{ fontSize: 12, color: MUTE, marginBottom: 6 }}>Seçilen dosya: {values[f.id].name}</div>}
                        <label style={{ ...btnGhost(false), display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
                          <Plus size={13} /> {uploadingId === f.id ? "Yükleniyor…" : "Dosya Yükle"}
                          <input type="file" onChange={(e) => uploadSingle(f, e)} disabled={uploadingId === f.id} style={{ display: "none" }} />
                        </label>
                      </div>
                    ) : f.type === "file-multi" ? (
                      <div>
                        {(values[f.id] || []).length > 0 && (
                          <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 8 }}>
                            {values[f.id].map((file, i) => (
                              <div key={i} style={{ fontSize: 12, color: MUTE, display: "flex", justifyContent: "space-between", alignItems: "center", background: CREAM, borderRadius: 4, padding: "4px 8px" }}>
                                <span>{file.name}</span>
                                <button onClick={() => setVal(f.id, values[f.id].filter((_, j) => j !== i))} style={{ background: "none", border: "none", cursor: "pointer", color: MUTE }}><X size={12} /></button>
                              </div>
                            ))}
                          </div>
                        )}
                        <label style={{ ...btnGhost(false), display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
                          <Plus size={13} /> {uploadingId === f.id ? "Yükleniyor…" : "Dosya Yükle (çoklu)"}
                          <input type="file" multiple onChange={(e) => uploadMulti(f, e)} disabled={uploadingId === f.id} style={{ display: "none" }} />
                        </label>
                      </div>
                    ) : <input style={inputStyle} value={values[f.id] || ""} onChange={(e) => setVal(f.id, e.target.value)} />}
                </Field>
              );
            })}
            <button onClick={submit} style={{ ...btnPrimary, width: "100%", marginTop: 8 }}>Gönder</button>
          </>
        )}
      </div>
    </div>
  );
}

