function ContactPage({ contact, onSubmit }) {
  const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [subject, setSubject] = useState(""); const [message, setMessage] = useState("");
  const [done, setDone] = useState(false);
  const submit = () => { if (!name || !email || !message) { alert("Ad, e-posta ve mesaj alanlarını doldurun."); return; } onSubmit({ name, email, subject, message }); setDone(true); setName(""); setEmail(""); setSubject(""); setMessage(""); };
  return (
    <div style={{ padding: 24, display: "flex", gap: 28, flexWrap: "wrap" }}>
      <div style={{ flex: "1 1 320px", background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 24 }}>
        <div style={{ fontSize: 18, marginBottom: 16 }}>Bize Ulaşın</div>
        {done ? <div style={{ fontSize: 14, color: MUTE }}><Check size={16} style={{ verticalAlign: "middle", marginRight: 6, color: CURTAIN }} />Mesajınız iletildi.</div> : (
          <>
            <Field label="Ad Soyad"><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} /></Field>
            <Field label="E-posta"><input style={inputStyle} value={email} onChange={(e) => setEmail(e.target.value)} /></Field>
            <Field label="Konu"><input style={inputStyle} value={subject} onChange={(e) => setSubject(e.target.value)} /></Field>
            <Field label="Mesaj"><textarea rows={5} style={{ ...inputStyle, resize: "vertical" }} value={message} onChange={(e) => setMessage(e.target.value)} /></Field>
            <button onClick={submit} style={{ ...btnPrimary, width: "100%" }}>Gönder</button>
          </>
        )}
      </div>
      <div style={{ flex: "1 1 260px" }}>
        <div style={{ fontSize: 14, display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}><Mail size={15} color={CURTAIN} /> {contact.email}</div>
        <div style={{ fontSize: 14, display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}><Phone size={15} color={CURTAIN} /> {contact.phone}</div>
        <div style={{ fontSize: 14, display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}><MapPin size={15} color={CURTAIN} /> {contact.address}</div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {Object.entries(contact.social).filter(([, v]) => v).map(([k, v]) => (
            <a key={k} href={v} target="_blank" rel="noreferrer" style={{ ...btnGhost(false), textDecoration: "none", textTransform: "capitalize" }}>{k}</a>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ---------- account (login / register / profile) ---------- */
const socialBtnStyle = { width: "100%", padding: "10px 0", borderRadius: 6, border: `1px solid ${LINE}`, background: "white", color: INK, cursor: "pointer", fontFamily: SERIF, fontSize: 13 };

function AccountModal({ onClose, onLoginEmail, onRegisterEmail, onSocial }) {
  const [mode, setMode] = useState("login");
  const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState("");
  const [err, setErr] = useState("");

  const [submitting, setSubmitting] = useState(false);
  const submit = async () => {
    setErr("");
    if (mode === "login") {
      setSubmitting(true);
      const r = await onLoginEmail(email, password);
      setSubmitting(false);
      if (r?.error) { setErr(r.error); return; }
      onClose();
    } else {
      if (!name.trim() || !email.trim() || !password) { setErr("Tüm alanları doldurun."); return; }
      if (password.length < 4) { setErr("Şifre en az 4 karakter olmalı."); return; }
      if (password !== confirm) { setErr("Şifreler eşleşmiyor."); return; }
      setSubmitting(true);
      const r = await onRegisterEmail(name, email, password);
      setSubmitting(false);
      if (r?.error) { setErr(r.error); return; }
      onClose();
    }
  };

  const social = (provider) => {
    const n = window.prompt(`(Önizleme) ${provider} hesabınızdaki adınız:`);
    if (!n) return;
    const e = window.prompt(`(Önizleme) ${provider} hesabınızdaki e-posta adresiniz:`);
    if (!e) return;
    const r = onSocial(provider, n, e);
    if (r?.error) { setErr(r.error); return; }
    onClose();
  };

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(27,22,19,0.55)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 90, padding: 16 }}>
      <div onClick={(e) => e.stopPropagation()} style={{ background: "white", borderRadius: 8, width: "100%", maxWidth: 400, padding: 26, maxHeight: "90vh", overflowY: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 14 }}>
          <div style={{ fontSize: 18 }}>{mode === "login" ? "Giriş Yap" : "Kayıt Ol"}</div>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: MUTE }}><X size={18} /></button>
        </div>
        <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
          <button onClick={() => { setMode("login"); setErr(""); }} style={{ ...btnGhost(mode === "login"), flex: 1 }}>Giriş Yap</button>
          <button onClick={() => { setMode("register"); setErr(""); }} style={{ ...btnGhost(mode === "register"), flex: 1 }}>Kayıt Ol</button>
        </div>
        {mode === "register" && <Field label="Ad Soyad"><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} /></Field>}
        <Field label="E-posta"><input style={inputStyle} value={email} onChange={(e) => setEmail(e.target.value)} /></Field>
        <Field label="Şifre"><input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} /></Field>
        {mode === "register" && <Field label="Şifre (Tekrar)"><input type="password" style={inputStyle} value={confirm} onChange={(e) => setConfirm(e.target.value)} /></Field>}
        {err && <div style={{ color: CURTAIN, fontSize: 12, marginBottom: 10 }}>{err}</div>}
        <button onClick={submit} disabled={submitting} style={{ ...btnPrimary, width: "100%", opacity: submitting ? 0.7 : 1 }}>{submitting ? "İşleniyor…" : mode === "login" ? "Giriş Yap" : "Hesap Oluştur"}</button>
        <div style={{ textAlign: "center", fontSize: 12, color: MUTE, margin: "18px 0 10px" }}>veya şununla devam et</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <button onClick={() => social("Google")} style={socialBtnStyle}>Google ile devam et</button>
          <button onClick={() => social("Facebook")} style={socialBtnStyle}>Facebook ile devam et</button>
        </div>
        <div style={{ fontSize: 10, color: MUTE, marginTop: 12, lineHeight: 1.5 }}>Bu önizleme ortamında sosyal girişler simüle edilir; gerçek Google/Facebook bağlantısı için bir sunucu ve API anahtarları gerekir.</div>
      </div>
    </div>
  );
}

function ProfilePage({ user, onUpdate, onChangePassword }) {
  const [uploading, setUploading] = useState(false);
  const uploadPhoto = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setUploading(true);
    try {
      const dataUrl = await fileToDataURL(file);
      const key = imgKey("user", user.id, "photo");
      await window.storage.set(key, dataUrl, true);
      imgCache[key] = dataUrl;
      onUpdate({ photo: key });
    } catch (err) {
      window.alert("Fotoğraf yüklenemedi.");
    }
    setUploading(false);
  };

  const [curPass, setCurPass] = useState(""); const [newPass, setNewPass] = useState(""); const [confirmPass, setConfirmPass] = useState(""); const [pwMsg, setPwMsg] = useState("");
  const [savingPw, setSavingPw] = useState(false);
  const savePassword = async () => {
    setSavingPw(true);
    const r = await onChangePassword(curPass, newPass, confirmPass);
    setSavingPw(false);
    if (r?.error) { setPwMsg(r.error); return; }
    setPwMsg("Şifre güncellendi.");
    setCurPass(""); setNewPass(""); setConfirmPass("");
  };

  if (!user) return null;
  return (
    <div style={{ padding: 24, maxWidth: 460, margin: "0 auto" }}>
      <div style={{ fontSize: 22, marginBottom: 20 }}>Profilim</div>
      <div style={{ display: "flex", gap: 16, alignItems: "center", marginBottom: 24 }}>
        <div style={{ width: 84, height: 84, borderRadius: "50%", overflow: "hidden", background: CREAM, flexShrink: 0 }}>
          <Img src={user.photo} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        </div>
        <div>
          <label style={{ ...btnGhost(false), display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
            <Plus size={13} /> {uploading ? "Yükleniyor…" : "Fotoğraf Değiştir"}
            <input type="file" accept="image/*" onChange={uploadPhoto} disabled={uploading} style={{ display: "none" }} />
          </label>
          <div style={{ fontSize: 11, color: MUTE, marginTop: 8 }}>{user.email} · {roleLabel(user.role)}{user.role === "crew" && user.crewTitle ? ` (${user.crewTitle})` : ""}</div>
        </div>
      </div>
      <Field label="Ad Soyad"><input style={inputStyle} value={user.name} onChange={(e) => onUpdate({ name: e.target.value })} /></Field>

      {user.provider === "email" ? (
        <div style={{ borderTop: `1px solid ${LINE}`, paddingTop: 18, marginTop: 10 }}>
          <div style={{ fontSize: 15, marginBottom: 12 }}>Şifre Değiştir</div>
          <Field label="Mevcut Şifre"><input type="password" style={inputStyle} value={curPass} onChange={(e) => setCurPass(e.target.value)} /></Field>
          <Field label="Yeni Şifre"><input type="password" style={inputStyle} value={newPass} onChange={(e) => setNewPass(e.target.value)} /></Field>
          <Field label="Yeni Şifre (Tekrar)"><input type="password" style={inputStyle} value={confirmPass} onChange={(e) => setConfirmPass(e.target.value)} /></Field>
          {pwMsg && <div style={{ fontSize: 12, marginBottom: 10, color: pwMsg === "Şifre güncellendi." ? "#3E6B32" : CURTAIN }}>{pwMsg}</div>}
          <button onClick={savePassword} disabled={savingPw} style={{ ...btnPrimary, opacity: savingPw ? 0.7 : 1 }}>{savingPw ? "Güncelleniyor…" : "Şifreyi Güncelle"}</button>
        </div>
      ) : (
        <div style={{ fontSize: 12, color: MUTE, marginTop: 10 }}>{user.provider} hesabıyla giriş yaptınız; şifreniz bu sitede saklanmıyor.</div>
      )}
    </div>
  );
}

function TicketReceiptBox({ eventId, order, onUploadReceipt }) {
  const [uploading, setUploading] = useState(false);
  const upload = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setUploading(true);
    try {
      const dataUrl = await fileToDataURL(file);
      const key = imgKey("receipt", eventId, order.id);
      await window.storage.set(key, dataUrl, true);
      imgCache[key] = dataUrl;
      onUploadReceipt(eventId, order.id, { key, name: file.name });
    } catch (err) {
      window.alert("Dekont yüklenemedi. Daha küçük bir dosya deneyin.");
    }
    setUploading(false);
  };

  if (order.method !== "eft" || order.status === "İptal Edildi") return null;

  if (order.receipt) {
    return (
      <div style={{ marginTop: 10, fontSize: 12, color: "#3E6B32", display: "flex", alignItems: "center", gap: 6 }}>
        <Check size={13} /> Dekont yüklendi — <FileValueLink value={order.receipt} />
      </div>
    );
  }
  return (
    <div style={{ marginTop: 10, background: "#FBEFC2", border: "1px solid #E4C766", borderRadius: 6, padding: "10px 12px" }}>
      <div style={{ fontSize: 12, color: "#4A3B0E", marginBottom: 8 }}>📌 Bu sipariş için henüz dekont yüklemediniz. Ödemenizin hızlı onaylanması için banka dekontunuzun fotoğrafını yükleyin.</div>
      <label style={{ ...btnGhost(false), background: "white", display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer", fontSize: 12 }}>
        <Plus size={13} /> {uploading ? "Yükleniyor…" : "Dekont Fotoğrafı Yükle"}
        <input type="file" accept="image/*,.pdf" onChange={upload} disabled={uploading} style={{ display: "none" }} />
      </label>
    </div>
  );
}

function MyTicketsPage({ user, data, bookings, onCancel, onUploadReceipt }) {
  const rows = Object.entries(bookings).flatMap(([eventId, b]) => (b.orders || []).filter((o) => o.userId === user.id).map((o) => ({ eventId, order: o })));
  rows.sort((a, b) => new Date(b.order.date) - new Date(a.order.date));

  return (
    <div style={{ padding: 24, maxWidth: 640, margin: "0 auto" }}>
      <div style={{ fontSize: 22, marginBottom: 20 }}>Biletlerim</div>
      {rows.length === 0 ? (
        <div style={{ color: MUTE, fontSize: 14 }}>Henüz bilet almadınız.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {rows.map(({ eventId, order }) => {
            const ev = data.events.find((e) => e.id === eventId);
            const show = ev ? data.shows.find((s) => s.id === ev.showId) : null;
            return (
              <div key={order.id} style={{ background: "white", border: `1px solid ${LINE}`, borderRadius: 8, padding: 16 }}>
                <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                  <div>
                    <div style={{ fontSize: 15 }}>{show?.title || "—"}</div>
                    <div style={{ fontSize: 12, color: MUTE, marginTop: 4 }}>{ev ? `${fmtDate(ev.date)} · ${ev.time} · ${ev.location}` : ""}</div>
                    <div style={{ fontSize: 12, color: MUTE, marginTop: 4 }}>{order.seats.length} koltuk · {order.total}₺ · Sipariş No: {order.id}</div>
                  </div>
                  <span style={{ fontSize: 11, padding: "4px 10px", borderRadius: 999, background: CREAM, color: statusColor(order.status), height: "fit-content" }}>{order.status}</span>
                </div>
                <TicketReceiptBox eventId={eventId} order={order} onUploadReceipt={onUploadReceipt} />
                {order.status !== "İptal Edildi" && (
                  <button onClick={() => { if (window.confirm("Bu bileti iptal etmek istiyor musunuz?")) onCancel(eventId, order.id); }} style={{ ...btnGhost(false), color: CURTAIN, marginTop: 12 }}>Bileti İptal Et</button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

