function AdminMenu({ data, setData }) {
  const [editId, setEditId] = useState(null);

  const findItem = (id) => {
    for (const m of data.menu) {
      if (m.id === id) return { item: m, parentId: null };
      for (const c of m.children || []) if (c.id === id) return { item: c, parentId: m.id };
    }
    return { item: null, parentId: null };
  };
  const { item, parentId } = findItem(editId);

  const update = (patch) => {
    if (parentId) {
      setData({ ...data, menu: data.menu.map((m) => (m.id === parentId ? { ...m, children: m.children.map((c) => (c.id === editId ? { ...c, ...patch } : c)) } : m)) });
    } else {
      setData({ ...data, menu: data.menu.map((m) => (m.id === editId ? { ...m, ...patch } : m)) });
    }
  };
  const remove = (id) => {
    const { parentId: pid } = findItem(id);
    if (pid) {
      setData({ ...data, menu: data.menu.map((m) => (m.id === pid ? { ...m, children: m.children.filter((c) => c.id !== id) } : m)) });
    } else {
      setData({ ...data, menu: data.menu.filter((m) => m.id !== id) });
    }
    if (editId === id) setEditId(null);
  };
  const move = (id, dir) => {
    const idx = data.menu.findIndex((m) => m.id === id);
    const j = idx + dir;
    if (j < 0 || j >= data.menu.length) return;
    const next = data.menu.slice();
    [next[idx], next[j]] = [next[j], next[idx]];
    setData({ ...data, menu: next });
  };
  const moveChild = (parentIdArg, id, dir) => {
    setData({ ...data, menu: data.menu.map((m) => {
      if (m.id !== parentIdArg) return m;
      const idx = m.children.findIndex((c) => c.id === id);
      const j = idx + dir;
      if (j < 0 || j >= m.children.length) return m;
      const next = m.children.slice();
      [next[idx], next[j]] = [next[j], next[idx]];
      return { ...m, children: next };
    }) });
  };

  const addBuiltin = (target, label) => setData({ ...data, menu: [...data.menu, { id: target, type: "builtin", label, target, children: [] }] });
  const addPage = (e) => {
    const pageId = e.target.value; e.target.value = "";
    if (!pageId) return;
    const pg = data.pages.find((p) => p.id === pageId);
    if (!pg) return;
    setData({ ...data, menu: [...data.menu, { id: uid(), type: "page", label: pg.title, pageId: pg.id, children: [] }] });
  };
  const addForm = (e) => {
    const formId = e.target.value; e.target.value = "";
    if (!formId) return;
    const f = data.forms.find((x) => x.id === formId);
    if (!f) return;
    setData({ ...data, menu: [...data.menu, { id: uid(), type: "form", label: f.title, formId: f.id, children: [] }] });
  };
  const addLink = () => { const ni = { id: uid(), type: "link", label: "Yeni Bağlantı", url: "", children: [] }; setData({ ...data, menu: [...data.menu, ni] }); setEditId(ni.id); };

  const addChildPage = (parentIdArg, e) => {
    const pageId = e.target.value; e.target.value = "";
    if (!pageId) return;
    const pg = data.pages.find((p) => p.id === pageId);
    if (!pg) return;
    const nc = { id: uid(), type: "page", label: pg.title, pageId: pg.id, children: [] };
    setData({ ...data, menu: data.menu.map((m) => (m.id === parentIdArg ? { ...m, children: [...(m.children || []), nc] } : m)) });
  };
  const addChildForm = (parentIdArg, e) => {
    const formId = e.target.value; e.target.value = "";
    if (!formId) return;
    const f = data.forms.find((x) => x.id === formId);
    if (!f) return;
    const nc = { id: uid(), type: "form", label: f.title, formId: f.id, children: [] };
    setData({ ...data, menu: data.menu.map((m) => (m.id === parentIdArg ? { ...m, children: [...(m.children || []), nc] } : m)) });
  };
  const addChildLink = (parentIdArg) => {
    const nc = { id: uid(), type: "link", label: "Yeni Bağlantı", url: "", children: [] };
    setData({ ...data, menu: data.menu.map((m) => (m.id === parentIdArg ? { ...m, children: [...(m.children || []), nc] } : m)) });
    setEditId(nc.id);
  };

  const missingBuiltins = BUILTIN_PAGES.filter(([id]) => !data.menu.some((m) => m.type === "builtin" && m.target === id));
  const pageTitle = (pageId) => data.pages.find((p) => p.id === pageId)?.title || "—";
  const formTitle = (formId) => data.forms.find((f) => f.id === formId)?.title || "—";
  const typeLabel = (t) => ({ builtin: "Sayfa", page: "Özel Sayfa", form: "Form", link: "Bağlantı" }[t] || t);

  if (item) {
    return (
      <Panel title="Menü Öğesi" right={<button onClick={() => setEditId(null)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTE }}>Listeye dön</button>}>
        <div style={{ maxWidth: 560 }}>
          <Field label="Menüde Görünen Ad"><input style={inputStyle} value={item.label} onChange={(e) => update({ label: e.target.value })} /></Field>
          {item.type === "builtin" && <div style={{ fontSize: 12, color: MUTE, marginBottom: 14 }}>Bu, sitenin hazır "{BUILTIN_PAGES.find(([id]) => id === item.target)?.[1]}" sayfasına bağlıdır — sadece görünen adını değiştirebilirsiniz.</div>}
          {item.type === "link" && <Field label="Bağlantı URL"><input style={inputStyle} value={item.url} onChange={(e) => update({ url: e.target.value })} placeholder="https://…" /></Field>}
          {item.type === "page" && <div style={{ fontSize: 12, color: MUTE, marginBottom: 14 }}>Bu menü öğesi "<strong>{pageTitle(item.pageId)}</strong>" sayfasına bağlıdır. İçeriğini "Sayfalar" sekmesinden düzenleyebilirsiniz.</div>}
          {item.type === "form" && <div style={{ fontSize: 12, color: MUTE, marginBottom: 14 }}>Bu menü öğesi "<strong>{formTitle(item.formId)}</strong>" formuna bağlıdır. İçeriğini "Formlar" sekmesinden düzenleyebilirsiniz.</div>}
          <button onClick={() => remove(item.id)} style={{ ...btnGhost(false), color: CURTAIN, display: "flex", alignItems: "center", gap: 6, marginTop: 12 }}><Trash2 size={13} /> Menüden Kaldır</button>
        </div>
      </Panel>
    );
  }

  return (
    <Panel title="Menüler" right={
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
        <select style={{ ...inputStyle, width: "auto" }} defaultValue="" onChange={addPage}>
          <option value="">+ Sayfa Ekle…</option>
          {data.pages.map((p) => <option key={p.id} value={p.id}>{p.title}</option>)}
        </select>
        <select style={{ ...inputStyle, width: "auto" }} defaultValue="" onChange={addForm}>
          <option value="">+ Form Ekle…</option>
          {data.forms.map((f) => <option key={f.id} value={f.id}>{f.title}</option>)}
        </select>
        <button onClick={addLink} style={{ ...btnGhost(false), display: "flex", alignItems: "center", gap: 6 }}><Plus size={13} /> Bağlantı</button>
      </div>
    }>
      <div style={{ fontSize: 12, color: MUTE, marginBottom: 14 }}>Üst menüde görünen sekmeleri buradan sıralayın, adlarını değiştirin, kaldırın; "Sayfalar" ve "Formlar" sekmelerinde oluşturduklarınızı veya dış bağlantıları ekleyin. Her öğenin altına alt menü (submenu) ekleyebilirsiniz.</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: missingBuiltins.length ? 18 : 0 }}>
        {data.menu.map((m, i) => (
          <div key={m.id} style={{ border: `1px solid ${LINE}`, borderRadius: 6, padding: 10 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span style={{ fontSize: 11, color: MUTE, width: 64, flexShrink: 0 }}>{typeLabel(m.type)}</span>
              <div onClick={() => setEditId(m.id)} style={{ flex: 1, cursor: "pointer", fontSize: 13 }}>{m.label}</div>
              <button onClick={() => move(m.id, -1)} disabled={i === 0} style={{ background: "none", border: "none", cursor: i === 0 ? "default" : "pointer", color: i === 0 ? LINE : MUTE }}>▲</button>
              <button onClick={() => move(m.id, 1)} disabled={i === data.menu.length - 1} style={{ background: "none", border: "none", cursor: i === data.menu.length - 1 ? "default" : "pointer", color: i === data.menu.length - 1 ? LINE : MUTE }}>▼</button>
              <button onClick={() => remove(m.id)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTE }}><Trash2 size={14} /></button>
            </div>

            <div style={{ marginLeft: 20, marginTop: 8, display: "flex", flexDirection: "column", gap: 6 }}>
              {(m.children || []).map((c, ci) => (
                <div key={c.id} style={{ display: "flex", alignItems: "center", gap: 8, background: CREAM, borderRadius: 6, padding: "6px 10px" }}>
                  <span style={{ fontSize: 10, color: MUTE, width: 56, flexShrink: 0 }}>{typeLabel(c.type)}</span>
                  <div onClick={() => setEditId(c.id)} style={{ flex: 1, cursor: "pointer", fontSize: 12 }}>{c.label}</div>
                  <button onClick={() => moveChild(m.id, c.id, -1)} disabled={ci === 0} style={{ background: "none", border: "none", cursor: ci === 0 ? "default" : "pointer", color: ci === 0 ? LINE : MUTE, fontSize: 11 }}>▲</button>
                  <button onClick={() => moveChild(m.id, c.id, 1)} disabled={ci === (m.children || []).length - 1} style={{ background: "none", border: "none", cursor: ci === (m.children || []).length - 1 ? "default" : "pointer", color: ci === (m.children || []).length - 1 ? LINE : MUTE, fontSize: 11 }}>▼</button>
                  <button onClick={() => remove(c.id)} style={{ background: "none", border: "none", cursor: "pointer", color: MUTE }}><Trash2 size={12} /></button>
                </div>
              ))}
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <select style={{ ...inputStyle, width: "auto", fontSize: 11, padding: "5px 8px" }} defaultValue="" onChange={(e) => addChildPage(m.id, e)}>
                  <option value="">+ Alt Sayfa…</option>
                  {data.pages.map((p) => <option key={p.id} value={p.id}>{p.title}</option>)}
                </select>
                <select style={{ ...inputStyle, width: "auto", fontSize: 11, padding: "5px 8px" }} defaultValue="" onChange={(e) => addChildForm(m.id, e)}>
                  <option value="">+ Alt Form…</option>
                  {data.forms.map((f) => <option key={f.id} value={f.id}>{f.title}</option>)}
                </select>
                <button onClick={() => addChildLink(m.id)} style={{ ...btnGhost(false), fontSize: 11, padding: "5px 8px" }}>+ Alt Bağlantı</button>
              </div>
            </div>
          </div>
        ))}
        {data.menu.length === 0 && <div style={{ fontSize: 13, color: MUTE }}>Menü boş.</div>}
      </div>
      {missingBuiltins.length > 0 && (
        <div>
          <div style={{ fontSize: 12, color: MUTE, marginBottom: 8 }}>Menüden kaldırılmış hazır sayfalar:</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {missingBuiltins.map(([id, label]) => <button key={id} onClick={() => addBuiltin(id, label)} style={btnGhost(false)}>+ {label}</button>)}
          </div>
        </div>
      )}
    </Panel>
  );
}

